#!/usr/bin/env python
"""Run MDL or LSTM across the multi-seed training-size ladder generated by
`scripts/generate_ladder_subsets.py` (8 sizes x 5 seeds = 40 runs per
model; 80 total across both models, all against the same fixed
validation/test splits).

For a given (seed, size), both models load their training data via
`emotion_ait.sampling.load_ladder_subset_dataframe`, guaranteeing they
train on exactly the same example ids.

Usage
-----
    python scripts/run_ladder_experiments.py --model mdl
    python scripts/run_ladder_experiments.py --model lstm
    python scripts/run_ladder_experiments.py --model mdl --sizes 100 500 --seeds 42 43
"""

from __future__ import annotations

import argparse
import logging
import sys
from pathlib import Path

import pandas as pd

REPO_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(REPO_ROOT / "src"))

from emotion_ait.config import Config, load_config  # noqa: E402
from emotion_ait.experiments import run_experiment  # noqa: E402
from emotion_ait.interfaces import EmotionClassifier  # noqa: E402
from emotion_ait.sampling import load_ladder_subset_dataframe  # noqa: E402

logging.basicConfig(level=logging.INFO, format="%(levelname)s %(name)s: %(message)s")
logger = logging.getLogger("run_ladder_experiments")


def load_processed_df(config: Config) -> pd.DataFrame:
    """Load the already-prepared processed splits from disk (written by
    `scripts/prepare_data.py`); never re-filters or re-splits the data."""
    frames = []
    for split in config.dataset.splits:
        path = config.paths.processed_dir / f"{split}.csv"
        if not path.exists():
            raise FileNotFoundError(f"{path} not found; run `python scripts/prepare_data.py` first.")
        frames.append(pd.read_csv(path))
    return pd.concat(frames, ignore_index=True)


def build_model(model_name: str, seed: int, epochs: int, patience: int) -> tuple[EmotionClassifier, dict]:
    """Instantiate a fresh model for one run, plus its config_summary."""
    if model_name == "mdl":
        from emotion_ait.mdl_classifier import MDLClassifier

        model = MDLClassifier(n=3, smoothing="laplace", k=1.0)
        return model, {"n": model.n, "smoothing": model.smoothing, "k": model.k}

    if model_name == "lstm":
        from emotion_ait.lstm_classifier import LSTMClassifier

        model = LSTMClassifier(max_epochs=epochs, patience=patience, seed=seed)
        config_summary = {
            "embedding_dim": model.embedding_dim,
            "hidden_dim": model.hidden_dim,
            "num_layers": model.num_layers,
            "max_epochs": model.max_epochs,
            "learning_rate": model.learning_rate,
            "batch_size": model.batch_size,
            "patience": model.patience,
            "seed": model.seed,
        }
        return model, config_summary

    raise ValueError(f"Unknown model '{model_name}'; expected 'mdl' or 'lstm'.")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--model", required=True, choices=["mdl", "lstm"], help="Which model to run.")
    parser.add_argument("--config", type=Path, default=None, help="Path to a YAML config file.")
    parser.add_argument(
        "--sizes", type=int, nargs="+", default=None,
        help="Ladder sizes to run (default: config.sampling.ladder_sizes).",
    )
    parser.add_argument(
        "--seeds", type=int, nargs="+", default=None,
        help="Ladder seeds to run (default: config.sampling.ladder_seeds).",
    )
    parser.add_argument("--epochs", type=int, default=10, help="LSTM max epochs (ignored for MDL).")
    parser.add_argument("--patience", type=int, default=3, help="LSTM early-stopping patience (ignored for MDL).")
    args = parser.parse_args()

    config = load_config(args.config)
    processed_df = load_processed_df(config)
    sizes = args.sizes or config.sampling.ladder_sizes
    seeds = args.seeds or config.sampling.ladder_seeds

    total_runs = len(sizes) * len(seeds)
    run_index = 0
    for seed in seeds:
        for size in sizes:
            run_index += 1
            # "ladder_n<size>" is distinct from the existing single-seed
            # "train_abs<size>" / "train_pct<pct>" subset names (even for
            # overlapping sizes like 100/250/500/2500), so results and
            # predictions never collide with the original 9-subset runs.
            subset_name = f"ladder_n{size}"
            logger.info("[%d/%d] model=%s seed=%d size=%d", run_index, total_runs, args.model, seed, size)

            train_df = load_ladder_subset_dataframe(seed, size, processed_df, config)
            model, config_summary = build_model(args.model, seed, args.epochs, args.patience)

            record = run_experiment(
                model=model,
                model_name=args.model,
                subset_name=subset_name,
                processed_df=processed_df,
                config=config,
                config_summary=config_summary,
                train_df=train_df,
                seed=seed,
            )
            logger.info(
                "seed=%d size=%d: n=%d test_accuracy=%.4f test_macro_f1=%.4f",
                seed,
                size,
                record.train_subset_size,
                record.test_accuracy,
                record.test_macro_f1,
            )

    logger.info(
        "Done: %d runs for model=%s. Results: %s. Predictions: %s.",
        total_runs,
        args.model,
        config.paths.results_dir / "metrics" / "results.csv",
        config.paths.results_dir / "predictions",
    )


if __name__ == "__main__":
    main()
